  it('feeds a schema rejection back to the provider as a tool_result so the model can correct the call', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async input => `Sunny in ${input.location}`
    );

    let capturedToolResult = '';
    const provider = {
      round: 0,
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        this.round++;
        if (this.round === 1) {
          yield {type: 'tool_use', toolCall: {id: 'c1', name: 'weather', input: {}}};
          yield {type: 'stop', stopReason: 'tool_use'};
        } else if (this.round === 2) {
          const last = params.messages[params.messages.length - 1];
          if (last.role === 'user' && Array.isArray(last.content)) {
            capturedToolResult = (last.content[0] as any).content;
          }
          yield {type: 'text', text: 'Retry: '};
          yield {type: 'tool_use', toolCall: {id: 'c2', name: 'weather', input: {location: 'Paris'}}};
          yield {type: 'stop', stopReason: 'tool_use'};
        } else {
          yield {type: 'text', text: 'Done'};
          yield {type: 'stop', stopReason: 'end_turn'};
        }
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
    const result = await orchestrator.processMessage(createSession('weather?'));

    expect({
      result,
      rejected: capturedToolResult.includes('location') && capturedToolResult.includes('required'),
    }).toEqual({
      result: 'Retry: Done',
      rejected: true,
    });
  });
});

